/* Display-only Russian labels. The VALUES stay English: LANGS/SETS are data
   keys — dataUrl() builds data/<lang>/<SET>_FINAL.json from them. */
const RU_NAME = {
  "Italian":"Итальянский","German":"Немецкий","Spanish":"Испанский","French":"Французский",
  "Esperanto":"Эсперанто","Toki Pona":"Токи пона","English":"Английский",
  "Core":"Core","Pareto 1":"Pareto 1","Pareto 2":"Pareto 2",
  "Adept":"Adept","Advance":"Advance","German Roots":"German Roots","Greek Roots":"Greek Roots",
  "Norman Roots":"Norman Roots","Latin Roots":"Latin Roots"
};
function ruName(x){ return RU_NAME[x] || x; }
/* Russian needs three plural forms: 1 блок / 2 блока / 5 блоков */
function plu(n,a,b,c){ var m=n%100; if(m>=11&&m<=14) return c; var d=n%10; return d===1?a:(d>=2&&d<=4?b:c); }
