column1:
function normCards(cluster){
  // foreign: {TargetWord,Translation}; English: {TargetWord,definition[,syn,ant,pos]}
  return (cluster.cards||[]).map(c=>({ w:c.TargetWord,
    t: c.definition!=null?c.definition:(c.Translation!=null?c.Translation:''),
    syn:synOf(c), ant:antOf(c), pos:posOf(c) }));
}

column2:
function gloss(c){ if(c.Translation_ru!=null&&c.Translation_ru!=='')return c.Translation_ru;   // page locale first; English packs carry no localized glosses (immersion ruling) and fall through
  return c.definition!=null?c.definition:(c.Translation!=null?c.Translation:''); }
function normCards(cluster){
  // foreign: {TargetWord,Translation[,Translation_ru]}; English: {TargetWord,definition[,syn,ant,pos]}
  return (cluster.cards||[]).map(c=>({ w:c.TargetWord,
    t: gloss(c),
    syn:synOf(c), ant:antOf(c), pos:posOf(c) }));
}
